'use strict';
const $=s=>document.querySelector(s);
const curated=[
{full:'excalidraw/excalidraw',name:'Excalidraw',description:'A virtual whiteboard for sketching hand-drawn diagrams and bringing ideas to life.',category:'Design',language:'TypeScript',demo:'https://excalidraw.com',color:'#d9e7d0',ink:'#35452e',symbol:'✎'},
{full:'tldraw/tldraw',name:'tldraw',description:'An infinite canvas for your next big idea. Draw, collaborate, and build.',category:'Design',language:'TypeScript',demo:'https://www.tldraw.com',color:'#f0ede4',ink:'#292c27',symbol:'tl'},
{full:'hoppscotch/hoppscotch',name:'Hoppscotch',description:'A lightweight API development ecosystem. Send requests and explore responses.',category:'Developer tools',language:'TypeScript',demo:'https://hoppscotch.io',color:'#143d34',ink:'#99efc6',symbol:'H'},
{full:'CorentinTh/it-tools',name:'IT Tools',description:'Everyday tools for developers, from converters to generators, all in one place.',category:'Developer tools',language:'Vue',demo:'https://it-tools.tech',color:'#323057',ink:'#d6caff',symbol:'it'},
{full:'actualbudget/actual',name:'Actual Budget',description:'A personal finance app that puts your budget and your data back in your hands.',category:'Finance',language:'TypeScript',demo:'https://demo.actualbudget.org',color:'#302e55',ink:'#dbd2ff',symbol:'A'},
{full:'twentyhq/twenty',name:'Twenty',description:'A modern, flexible CRM you can adapt to the way your team works.',category:'Business',language:'TypeScript',demo:'https://demo.twenty.com',color:'#272a2d',ink:'#f4f4f4',symbol:'20'},
{full:'drawdb-io/drawdb',name:'drawDB',description:'Design database schemas visually and export the SQL when you’re ready.',category:'Developer tools',language:'JavaScript',demo:'https://www.drawdb.app/editor',color:'#193546',ink:'#a6d6e8',symbol:'db'},
{full:'AmruthPillai/Reactive-Resume',name:'Reactive Resume',description:'Create a beautiful resume and keep your personal information your own.',category:'Productivity',language:'TypeScript',demo:'https://rxresu.me',color:'#63362a',ink:'#f8c7a8',symbol:'r.'},
{full:'monkeytypegame/monkeytype',name:'Monkeytype',description:'A minimal, customizable typing test. Find your flow and improve your speed.',category:'Education',language:'TypeScript',demo:'https://monkeytype.com',color:'#323329',ink:'#e8d77b',symbol:'mt'},
{full:'benweet/stackedit',name:'StackEdit',description:'A full-featured Markdown editor in your browser. Write, preview, and publish.',category:'Productivity',language:'JavaScript',demo:'https://stackedit.io/app',color:'#294451',ink:'#b6d9e7',symbol:'#'},
{full:'AppFlowy-IO/AppFlowy',name:'AppFlowy',description:'An open-source workspace for notes, projects, and knowledge.',category:'Productivity',language:'Dart',demo:null,color:'#35443d',ink:'#c7e7d6',symbol:'A'},
{full:'calcom/cal.com',name:'Cal.com',description:'Scheduling infrastructure that makes it easier for people to meet.',category:'Business',language:'TypeScript',demo:null,color:'#e5e2da',ink:'#292b27',symbol:'Cal'}
];
const categories=['All projects','Design','Developer tools','Productivity','Business','Finance','Education','Other'];
let state={view:'discover',source:'github',category:'All projects',query:'',page:1,loading:false};
let discovered=[], catalog=[], searchToken=0, timer, toastTimer;
let session=null, visibleLimit=48, checkedCandidates=0, discoveryWarning='';
const D=RepoDiscovery;
const demoCache=readStore('reposhelf.demos.v2',{});
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let collection=readStore('reposhelf.collection.v1',{});if(!collection||typeof collection!=='object'||Array.isArray(collection))collection={};
let username=readStore('reposhelf.username.v1','');
function persist(){try{localStorage.setItem('reposhelf.collection.v1',JSON.stringify(collection));localStorage.setItem('reposhelf.username.v1',JSON.stringify(username))}catch{toast('Browser storage is unavailable; changes last for this session.')}}
function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function stars(n){return typeof n==='number'?(n>=1000?(n/1000).toFixed(n>=10000?0:1)+'k':String(n)):'—'}
function repoData(full){return curated.find(r=>r.full===full)||discovered.find(r=>r.full===full)||catalog.find(r=>r.full===full)||collection[full]?.repo}
function cover(r){return `<div class="cover-inner"><span class="cover-logo">${escape(r.symbol||r.name.slice(0,1).toUpperCase())}</span><span class="cover-title">${escape(r.name)}</span></div><span class="cover-kicker">${escape(r.category)}</span>${r.demo?'<span class="live-badge">Live demo</span>':''}${collection[r.full]?`<span class="fork-badge">${collection[r.full].verified?'Fork verified':'Tracked'}</span>`:''}`}
function coverStyle(r){return `--cover:${/^#[0-9a-f]{3,8}$/i.test(r.color)?r.color:'#25392f'};--ink:${/^#[0-9a-f]{3,8}$/i.test(r.ink)?r.ink:'#d1e5c5'}`}
function card(r){return `<article class="card"><button class="cover" style="${coverStyle(r)}" data-details="${escape(r.full)}" aria-label="View ${escape(r.name)} details">${cover(r)}</button><div class="card-heading"><h3><button data-details="${escape(r.full)}">${escape(r.name)}</button></h3></div><p class="repo-owner">${escape(r.full)}</p><p class="card-description">${escape(r.description)}</p><div class="card-bottom"><span class="star" title="GitHub stars">☆ ${stars(r.stars)}</span><span class="language">${escape(r.language||'Open source')}</span><button class="fork-button" data-details="${escape(r.full)}">${collection[r.full]?'View fork':'⑂ Fork repo'}</button></div></article>`}
function render(){
$('#fork-count').textContent=Object.keys(collection).length;
$('#section-heading').textContent=state.view==='collection'?'Your fork collection':'Find your next project';
$('#section-caption').textContent=state.view==='collection'?'A starting point for what you’ll build next.':'Good ideas deserve a head start.';
$('.feature').hidden=state.view==='collection';$('.intro').hidden=state.view==='collection';$('.source-control').hidden=state.view==='collection';
document.querySelectorAll('.nav').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false')});
$('#curated').classList.toggle('active',state.source==='curated');$('#github').classList.toggle('active',state.source==='github');
$('.categories').innerHTML=categories.map(c=>`<button class="category ${state.category===c?'active':''}" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('');
let repos=state.view==='collection'?Object.values(collection).map(x=>x.repo).filter(Boolean):state.source==='curated'?curated:discovered;
const q=state.query.toLowerCase();repos=repos.filter(r=>(!$('#demos').checked||r.demo)&&(state.category==='All projects'||r.category===state.category)&&(state.remote&&state.view==='discover'||!q||[r.full,r.name,r.description,r.language,(r.topics||[]).join(' ')].some(s=>String(s||'').toLowerCase().includes(q))));
repos=[...repos];const sort=$('#sort').value;if(sort==='stars')repos.sort((a,b)=>(b.stars??-1)-(a.stars??-1));if(sort==='forks')repos.sort((a,b)=>(b.forks??-1)-(a.forks??-1));if(sort==='newest')repos.sort((a,b)=>new Date(b.created||0)-new Date(a.created||0));if(sort==='updated')repos.sort((a,b)=>new Date(b.updated||0)-new Date(a.updated||0));if(sort==='name')repos.sort((a,b)=>a.name.localeCompare(b.name));
$('#result-count').textContent=`${repos.length.toLocaleString()} project${repos.length===1?'':'s'}${$('#demos').checked?' with live demos':''}`;
$('#data-note').textContent=state.view==='collection'?'Saved in this browser':state.source==='github'?`${catalog.length.toLocaleString()} indexed · ${checkedCandidates.toLocaleString()} checked live`:'Handpicked, publicly available GitHub repositories';
$('#grid').innerHTML=repos.slice(0,visibleLimit).map(card).join('')||`<div class="empty"><h3>${state.loading?'Finding your next project…':state.view==='collection'&&!Object.keys(collection).length?'Your next project starts here.':'No projects found'}</h3><p>${state.loading?'Checking repository README files for live demo links.':state.view==='collection'&&!Object.keys(collection).length?'Explore a project, fork it on GitHub, then add it here. You can also sync your public forks with your GitHub username.':'Try a different search or category, or switch off “Live demos only” to include more repositories.'}</p>${!state.loading?'<button class="button outline" id="reset-filters">Reset filters</button>':''}</div>`;
const moreLocal=repos.length>visibleLimit;
$('#load-more').hidden=state.view==='collection'||state.source!=='github'||(!moreLocal&&state.remote&&!hasMore());
$('#load-more').disabled=state.loading;$('#load-more').textContent=state.loading?'Finding more demos…':moreLocal?'Show more projects':state.remote?'Find more on GitHub':'Search beyond the catalog';
$('#account-button span:last-child').textContent=username?`@${username}`:'GitHub account';
}
function showDetails(full){const r=repoData(full);if(!r)return;const entry=collection[full], url=`https://github.com/${full}`;
$('#detail-content').innerHTML=`<p class="eyebrow">${escape(r.category)} · OPEN SOURCE</p><div class="cover" style="${coverStyle(r)}">${cover(r)}</div><h2>${escape(r.name)}</h2><p class="repo-owner">${escape(r.full)}</p><p>${escape(r.description)}</p><div class="detail-meta"><span>☆ ${stars(r.stars)} stars</span><span>⑂ ${stars(r.forks)} forks</span><span>${escape(r.language||'Open source')}</span>${r.created?`<span>Created ${escape(new Date(r.created).toLocaleDateString())}</span>`:''}${r.license?`<span>${escape(r.license)} license</span>`:''}${r.updated?`<span>Updated ${escape(new Date(r.updated).toLocaleDateString())}</span>`:''}</div><div class="detail-actions">${r.demo?`<a class="button lime" href="${escape(safeUrl(r.demo)||url)}" target="_blank" rel="noopener">Try live demo ↗</a>`:''}<a class="button outline" href="${url}" target="_blank" rel="noopener">View repository</a><a class="button outline" href="${url}/fork" target="_blank" rel="noopener" id="fork-link">⑂ Fork on GitHub</a></div><p class="small">${r.demo?'Demo links may lead to a hosted app or a public playground.':'This listing does not have a confirmed live demo.'} Check the repository’s license before reusing its code.</p><div class="tracking"><p>${entry?(entry.verified?`Public fork verified in @${escape(username)}.`:'Manually tracked in this browser.'): 'After forking on GitHub, add this project to your collection.'}</p><button class="button ${entry?'outline':'lime'}" id="track-repo">${entry?'Remove from collection':'I’ve forked this'}</button></div>${entry?.url?`<p><a href="${escape(safeUrl(entry.url)||url)}" target="_blank" rel="noopener">Open my fork ↗</a></p>`:''}`;
$('#track-repo').onclick=()=>{if(collection[full]){delete collection[full];toast('Removed from your collection')}else{collection[full]={repo:r,verified:false,added:new Date().toISOString()};toast('Added to your collection')}persist();render();showDetails(full)};
if(!$('#detail').open)$('#detail').showModal();
}
async function api(path){const res=await fetch(`https://api.github.com${path}`,{headers:{Accept:'application/vnd.github+json'},signal:AbortSignal.timeout(12000)});if(!res.ok){if(res.status===403||res.status===429)throw new Error('GitHub’s public API limit was reached. Try again later. Your saved collection is still available.');if(res.status===404)throw new Error('GitHub could not find that public account or repository.');throw new Error(`GitHub is unavailable (${res.status}). Please try again.`)}return res.json()}
async function pool(items,fn,limit=4){let i=0;return Promise.all(Array.from({length:Math.min(limit,items.length)},async()=>{while(i<items.length){const n=i++;await fn(items[n],n)}}))}
async function hydrate(){let loaded=0;try{await pool(curated,async r=>{try{const d=await api(`/repos/${r.full}`);Object.assign(r,{stars:d.stargazers_count,forks:d.forks_count,created:d.created_at,updated:d.pushed_at,license:d.license?.spdx_id==='NOASSERTION'?null:d.license?.spdx_id});loaded++;if(collection[r.full])collection[r.full].repo=r}catch{}});render();if(!loaded&&state.source==='curated'&&state.view==='discover')$('#status').textContent='Live GitHub statistics are unavailable. You can still browse projects, open demos, and track forks.'}catch{}}
function classify(r){return D.classify(r)}
async function findDemo(repo){const key=repo.full.toLowerCase(),cached=demoCache[key];if(cached&&cached.updated===repo.updated&&Date.now()-cached.checked<7*86400000)return cached.demo;
let content=null;for(const path of ['README.md','readme.md','README.MD']){try{const res=await fetch(`https://raw.githubusercontent.com/${repo.full}/${encodeURIComponent(repo.branch||'main')}/${path}`,{signal:AbortSignal.timeout(7000)});if(res.status===404)continue;if(!res.ok)throw new Error('README temporarily unavailable');content=await res.text();break}catch{return undefined}}
const demo=D.extractDemo(content,repo.homepage);demoCache[key]={updated:repo.updated,checked:Date.now(),demo};return demo;}
function saveDemoCache(){try{const recent=Object.entries(demoCache).sort((a,b)=>b[1].checked-a[1].checked).slice(0,3000);localStorage.setItem('reposhelf.demos.v2',JSON.stringify(Object.fromEntries(recent)))}catch{}}
function hasMore(){return Boolean(session?.queries.some(q=>!q.done))}
function mergeRepos(items){const repos=new Map(discovered.map(r=>[r.full.toLowerCase(),r]));for(const r of items)repos.set(r.full.toLowerCase(),r);discovered=[...repos.values()]}
function useCatalog(){searchToken++;state.loading=false;state.remote=false;session=null;visibleLimit=48;checkedCandidates=0;discovered=[...catalog];$('#status').textContent='';render()}
async function loadCatalog(){try{const res=await fetch('catalog.json',{signal:AbortSignal.timeout(10000)});if(!res.ok)throw Error('Catalog unavailable');const data=await res.json();catalog=Array.isArray(data.repositories)?data.repositories.filter(r=>typeof r.full==='string'&&/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(r.full)&&typeof r.name==='string'&&D.demoUrl(r.demo)):[];const all=new Map(curated.map(r=>[r.full.toLowerCase(),r]));for(const r of catalog)all.set(r.full.toLowerCase(),r);catalog=[...all.values()];useCatalog();if(data.repositories.length<20)discover()}catch{catalog=[...curated];useCatalog();discover()}}
async function discover(append=false){const token=++searchToken;if(!append){state.remote=true;visibleLimit=48;checkedCandidates=0;discoveryWarning='';session={queries:D.searchQueries({query:state.query,category:state.category,demos:$('#demos').checked,newest:$('#sort').value==='newest'}).map(q=>({q,page:1,done:false})),next:0};discovered=state.query.trim()?[]:catalog.filter(r=>state.category==='All projects'||r.category===state.category)}
state.loading=true;$('#status').textContent='Searching GitHub and checking demo links…';render();let temporaryFailures=0;
try{for(let batch=0;batch<3&&hasMore();batch++){if(token!==searchToken)return;let task;for(let i=0;i<session.queries.length;i++){const index=session.next++%session.queries.length;if(!session.queries[index].done){task=session.queries[index];break}}if(!task)break;
const sort=$('#sort').value==='updated'?'updated':$('#sort').value==='forks'?'forks':'stars';const data=await api(`/search/repositories?q=${encodeURIComponent(task.q)}&sort=${sort}&order=desc&per_page=100&page=${task.page}`);if(token!==searchToken)return;task.page++;task.done=data.items.length<100||(task.page-1)*100>=Math.min(data.total_count??1000,1000);
const existing=new Map([...catalog,...discovered].map(r=>[r.full.toLowerCase(),r]));const results=data.items.map(d=>D.mapRepo(d));await pool(results,async r=>{if(token!==searchToken)return;const known=existing.get(r.full.toLowerCase());if(known?.demo)Object.assign(r,{demo:known.demo,name:known.name,color:known.color,ink:known.ink,symbol:known.symbol});else{const demo=await findDemo(r);if(demo===undefined)temporaryFailures++;else r.demo=demo;}if(token!==searchToken)return;checkedCandidates++;mergeRepos([r]);if(checkedCandidates%8===0)render()},8);if(token!==searchToken)return;saveDemoCache();render();const matches=discovered.filter(r=>(!$('#demos').checked||r.demo)&&(state.category==='All projects'||r.category===state.category));if(matches.length>=24)break;}
if(token!==searchToken)return;$('#status').textContent=`Checked ${checkedCandidates.toLocaleString()} repositories for demo links.${temporaryFailures?' Some READMEs could not be reached; they have not been marked as having no demo.':''}${hasMore()?' Keep exploring to search additional batches.':' All results in this search have been checked.'}${$('#sort').value==='newest'?' Newest live search covers the last 30 days; creation-date sorting applies to loaded results.':''}`;
}catch(e){if(token!==searchToken)return;discoveryWarning=e.message||'Could not reach GitHub.';$('#status').textContent=`${discoveryWarning} Loaded catalog results are still available. Use “Find more on GitHub” to retry.`}finally{if(token===searchToken){state.loading=false;render()}}}
async function syncForks(){const output=$('#sync-status');output.textContent='Checking your public GitHub forks…';let count=0,scanned=0;try{await api(`/users/${username}`);let forks=[];for(let page=1;page<=10;page++){const repos=await api(`/users/${username}/repos?type=owner&sort=updated&per_page=100&page=${page}`);scanned+=repos.length;forks.push(...repos.filter(r=>r.fork));if(repos.length<100)break}let failures=0;await pool(forks,async f=>{try{const d=await api(`/repos/${f.full_name}`);if(!d.parent)return;const full=d.parent.full_name;const existing=repoData(full);const r=existing||{full,name:d.parent.name,description:d.parent.description||'A public repository in your fork collection.',category:classify(d.parent),language:d.parent.language,stars:d.parent.stargazers_count,updated:d.parent.pushed_at,demo:null,color:'#25392f',ink:'#d1e5c5'};collection[full]={repo:r,verified:true,url:f.html_url,added:collection[full]?.added||new Date().toISOString()};count++}catch{failures++}});persist();render();output.textContent=`Verified ${count} public fork${count===1?'':'s'} for @${username}.${failures?' Some forks could not be checked; try syncing again later.':''}${scanned===1000?' Checked the 1,000 most recently updated repositories.':''} Private forks are not accessible.`;toast('Your fork collection has been updated')}catch(e){output.textContent=e.message||'Could not reach GitHub. Try again later.'}}
$('#account-button').onclick=()=>{$('#username').value=username;$('#sync-status').textContent='';$('#account').showModal()};
$('#account-form').onsubmit=e=>{e.preventDefault();const next=$('#username').value.trim();if(!/^[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,37}[a-zA-Z0-9])?$/.test(next)){$('#sync-status').textContent='Enter a valid GitHub username.';return}if(username.toLowerCase()!==next.toLowerCase()){Object.values(collection).forEach(e=>{e.verified=false;delete e.url})}username=next;persist();render();syncForks()};
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('click',e=>{const details=e.target.closest('[data-details]');if(details)showDetails(details.dataset.details);const cat=e.target.closest('[data-category]');if(cat){state.category=cat.dataset.category;if(state.source==='github'&&state.view==='discover')useCatalog();else render()}const nav=e.target.closest('[data-view]');if(nav){state.view=nav.dataset.view;if(state.view==='collection'){searchToken++;state.loading=false}$('#status').textContent='';render()}if(e.target.closest('#reset-filters')){state.category='All projects';state.query='';$('#search').value='';$('#demos').checked=false;render();if(state.source==='github'&&state.view==='discover')useCatalog()}});
$('#feature-details').onclick=()=>showDetails('excalidraw/excalidraw');
$('#curated').onclick=()=>{state.source='curated';visibleLimit=48;searchToken++;state.loading=false;$('#status').textContent='';render();hydrate()};$('#github').onclick=()=>{state.source='github';useCatalog()};
$('#search').oninput=e=>{state.query=e.target.value;clearTimeout(timer);if(state.source==='github'&&state.view==='discover'){useCatalog();if(state.query.trim())timer=setTimeout(()=>discover(),700)}else render()};
$('#demos').onchange=()=>{if(state.source==='github'&&state.view==='discover'&&(!$('#demos').checked||state.remote))discover();else render()};$('#sort').onchange=()=>{if(state.source==='github'&&state.view==='discover')useCatalog();else render()};$('#load-more').onclick=async()=>{const matches=discovered.filter(r=>(!$('#demos').checked||r.demo)&&(state.category==='All projects'||r.category===state.category)&&(state.remote||!state.query||[r.name,r.full,r.description,r.language,(r.topics||[]).join(' ')].some(v=>String(v||'').toLowerCase().includes(state.query.toLowerCase()))));if(matches.length>visibleLimit){visibleLimit+=48;render();return}const target=visibleLimit+48;await discover(state.remote);visibleLimit=Math.max(visibleLimit,target);render()};
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.querySelector('dialog[open]')){e.preventDefault();$('#search').focus()}});
render();loadCatalog();
